import {inspectPage,renderPage,textPlan,validateLayout,MODEL_VERSION,adaptDays} from './pdf-template-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let pdfjs,active=null,queue=Promise.resolve();
function exclusive(fn){const run=queue.catch(()=>{}).then(fn);queue=run;return run;}
function styles(){if(document.querySelector('#pdf-model-style'))return;const link=document.createElement('link');link.id='pdf-model-style';link.rel='stylesheet';link.href='pdf-template.css?v=1';document.head.append(link);}
async function open(file,progress=()=>{}){
  pdfjs||=await import('./vendor/pdfjs/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdfjs/pdf.worker.mjs',import.meta.url).href;
  const response=await fetch('/api/files/'+encodeURIComponent(file.id),{credentials:'same-origin'});if(!response.ok)throw Error('Não foi possível abrir o PDF original. Atualize sua sessão.');
  const data=new Uint8Array(await response.arrayBuffer());if(data.length>20*1024*1024)throw Error('Use um PDF de até 20 MB.');
  const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',data))].map(x=>x.toString(16).padStart(2,'0')).join('');
  const doc=await pdfjs.getDocument({data,fontExtraProperties:true,disableFontFace:false,isEvalSupported:false}).promise;
  if(doc.numPages>60){await doc.destroy();throw Error('Use um PDF de até 60 páginas.');}
  const fonts=[],pages=[];
  try{for(let n=1;n<=doc.numPages;n++){progress('Reconhecendo página '+n+' de '+doc.numPages+'…');const page=await doc.getPage(n),result=await inspectPage(page,document.createElement('canvas'),pdfjs.OPS);fonts.push(...result.fonts);pages.push(result.page);}
    if(!pages.some(p=>p.fields.length))throw Error('Este PDF é uma imagem ou usa texto em curvas. Para manter a diagramação e editar automaticamente, envie a versão PDF com texto selecionável ou o arquivo editável original.');
    let day=0;for(const p of pages){if(p.day)day=p.day;else if(p.fields.some(f=>/^(transporte|guia prático|muito|informações gerais)/i.test(f.text.trim())))day=0;p.day=day;for(const f of p.fields)f.day=day;}
    return {doc,fonts,layout:validateLayout({version:MODEL_VERSION,hash,pages})};
  }catch(e){await doc.destroy();throw e;}
}
export async function upload(file,api){
  if(file.size>20*1024*1024)throw Error('Use um PDF de até 20 MB.');
  const signed=await api.request('/templates/upload',{method:'POST',body:{name:file.name,size:file.size}});
  if(signed.direct){const response=await fetch(signed.uploadUrl,{method:'PUT',headers:{'Content-Type':'application/pdf'},body:file});if(!response.ok)throw Error('Falha no envio do PDF original. Tente novamente.');return signed.file;}
  const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});
  return api.request('/files',{method:'POST',body:{name:file.name,base64,purpose:'itinerary-template'}});
}
export async function review(model,ctx){
  styles();ctx.show('Reconhecendo o modelo','<p id="pdf-progress" role="status">Abrindo o PDF original…</p>');
  return exclusive(async()=>{
    const session=await open(model.file,text=>{const el=document.querySelector('#pdf-progress');if(el)el.textContent=text;});
    if(active)await active.doc.destroy();active=session;
    if(model.visualLayout?.hash===session.layout.hash)session.layout=structuredClone(model.visualLayout);
    ctx.show('Campos do modelo da agência','<div id="pdf-review-root"></div>');
    const root=document.querySelector('#pdf-review-root');if(root)mount(root,{session,model,ctx,review:true,autoClassify:!model.visualLayout});
  });
}
export function editorShell(r){styles();return '<div class="pdf-editor-heading"><div><span class="eyebrow">ROTEIRO · MODELO ORIGINAL</span><h1>'+esc(r.name)+'</h1><p>Preencha a viagem; o COS adapta os textos nos espaços do modelo.</p></div><a class="outline-button" href="roteiros.html">Voltar aos roteiros</a></div><div id="pdf-editor-root" data-id="'+esc(r.id)+'"><p role="status">Abrindo páginas e fontes originais…</p></div>';}
export async function edit(root,r,ctx){
  styles();return exclusive(async()=>{try{const session=await open(r.sourceFile,text=>{if(root.isConnected)root.textContent=text;});if(!root.isConnected){await session.doc.destroy();return;}if(session.layout.hash!==r.visualLayout.hash){await session.doc.destroy();throw Error('O original mudou. Importe novamente para não aplicar campos em posições incorretas.');}validateLayout(r.visualLayout);session.layout=r.visualLayout;if(active)await active.doc.destroy();active=session;mount(root,{session,r,ctx,review:false});}catch(e){root.textContent=e.message;}});
}
function mount(root,{session,model,r,ctx,review,autoClassify=false}){
  const layout=session.layout,values=review?{}:(r.fieldValues||={});let index=0,busy=false;
  root.innerHTML='<div class="pdf-workflow-note">'+(review?'O PDF é a base visual. Confira quais blocos mudam em cada viagem. O reconhecimento por IA usa o texto deste modelo.':'Cada página mantém o desenho original. Gere os textos, confira os avisos e baixe o PDF revisado.')+'</div><div class="pdf-toolbar"><label>Página <select id="pdf-page">'+layout.pages.map((p,i)=>'<option value="'+i+'">'+(i+1)+(p.day?' · Dia '+p.day:' · Geral')+'</option>').join('')+'</select></label><button type="button" class="outline-button" id="pdf-auto">'+(review?'Reconhecer campos com IA':'Preencher roteiro com IA')+'</button><button type="button" class="outline-button" id="pdf-page-ai">'+(review?'Reconhecer esta página':'Preencher esta página')+'</button><button type="button" class="primary-button" id="pdf-save">'+(review?'Salvar modelo':'Salvar roteiro')+'</button>'+(!review?'<button type="button" class="outline-button" id="pdf-download">Baixar PDF</button>':'')+'<button type="button" class="text-button" id="pdf-cancel" hidden>Parar após esta página</button></div>'+(!review?'<details class="pdf-brief-panel"><summary>Dados da viagem e instruções para a IA</summary><label class="form-field"><span>Descrição da viagem e intenção do roteiro</span><textarea id="pdf-brief" rows="4" maxlength="12000" placeholder="Viajantes, datas, destinos por dia, ritmo, preferências e serviços confirmados. Não é necessário reescrever o roteiro.">'+esc(r.brief||'')+'</textarea></label><label class="pdf-confirm"><input type="checkbox" id="pdf-art-reviewed" '+(r.artReviewed?'checked':'')+'> Conferi que fotos e mapas do original correspondem à nova viagem. O PDF exportado não leva os links antigos.</label></details>':'')+'<p class="pdf-status" role="status" aria-live="polite"></p><div class="pdf-workspace"><aside class="pdf-fields"></aside><div class="pdf-preview"><canvas aria-label="Página do roteiro original"></canvas></div></div>';
  const status=text=>{root.querySelector('.pdf-status').textContent=text;},canvas=root.querySelector('canvas'),fields=root.querySelector('.pdf-fields');
  const sourcePage=p=>session.doc.getPage(p.sourceNumber||p.number);
  const errors=()=>{const context=document.createElement('canvas').getContext('2d'),issues=[];for(const p of layout.pages)for(const f of p.fields)if(f.editable&&Object.hasOwn(values,f.id)&&values[f.id]!==f.text)try{textPlan(context,f,values[f.id],session.fonts);}catch(e){issues.push('Página '+p.number+': '+e.message);}return issues;};
  async function preview(){const p=layout.pages[index];try{await exclusive(()=>sourcePage(p).then(page=>renderPage(page,canvas,p,values,session.fonts)));}catch(e){status(e.message);}}
  function collect(){for(const el of fields.querySelectorAll('[data-field]')){const f=layout.pages[index].fields.find(f=>f.id===el.dataset.field);if(review){f.editable=el.checked;if(f.role==='pageNumber')continue;f.role=f.editable?(f.role==='fixed'?'content':f.role):'fixed';}else values[f.id]=el.value;}if(!review){r.brief=root.querySelector('#pdf-brief').value;r.artReviewed=root.querySelector('#pdf-art-reviewed').checked;}}
  function display(){const p=layout.pages[index];fields.innerHTML='<h2>'+ (review?'Campos reconhecidos':'Conteúdo da página')+'</h2><p class="form-hint">'+(review?'Marcados = variáveis. Desmarque marcas e textos que devem permanecer fixos.':'Os textos abaixo ocupam as mesmas posições do original.')+'</p>'+p.fields.filter(f=>review||f.editable).map(f=>'<label class="pdf-field">'+(review?'<span><input type="checkbox" data-field="'+f.id+'" '+(f.editable?'checked':'')+'> '+esc(f.label)+'</span><small>'+esc(f.text)+'</small>':'<span>'+esc(f.label)+'</span><textarea data-field="'+f.id+'" rows="'+Math.min(8,Math.max(2,f.lines||2))+'" maxlength="15000">'+esc(Object.hasOwn(values,f.id)?values[f.id]:f.text)+'</textarea><small>'+f.lines+' linha(s) no modelo</small>')+'</label>').join('');preview();}
  fields.addEventListener('input',()=>{collect();});fields.addEventListener('change',()=>{collect();preview();});if(!review){root.querySelector('#pdf-brief').addEventListener('input',collect);root.querySelector('#pdf-art-reviewed').addEventListener('change',collect);}root.querySelector('#pdf-page').onchange=e=>{collect();index=Number(e.target.value);display();};
  async function generate(all){if(busy)return;collect();if(!review&&!r.brief.trim()){status('Descreva a viagem para o COS adaptar os campos.');root.querySelector('.pdf-brief-panel').open=true;root.querySelector('#pdf-brief').focus();return;}busy=true;let stopped=false;root.querySelector('#pdf-cancel').hidden=false;root.querySelector('#pdf-cancel').onclick=()=>{stopped=true;status('Parando após esta página…');};root.querySelectorAll('button:not(#pdf-cancel),select').forEach(el=>el.disabled=true);
    try{const pages=all?layout.pages:[layout.pages[index]],outline=layout.pages.map(p=>'Página '+p.number+(p.day?' / Dia '+p.day:' / informações gerais')+': '+p.fields.slice(0,3).map(f=>f.label).join(', ')).join('\n');
      for(const p of pages){if(!root.isConnected)break;const selected=p.fields.filter(f=>review||f.editable);if(!selected.length)continue;status((review?'Reconhecendo':'Preenchendo')+' página '+p.number+' de '+layout.pages.length+'…');
        const requestFields=selected.map(f=>({...f,allowedCharacters:[...new Set(session.fonts.filter(font=>font.name===f.family).flatMap(font=>[...font.chars.keys()]))].join('')+' '}));
        let pending=requestFields;
        for(let attempt=0;attempt<(review?1:3)&&pending.length;attempt++){
          const result=await ctx.api.request('/templates/visual',{method:'POST',body:{mode:review?'classify':'fill',fields:pending,brief:review?'Identifique a estrutura deste modelo de roteiro.':r.brief,page:{number:p.number,day:p.day},outline,budget:attempt===0?.85:attempt===1?.6:.4}});
          for(const item of result.fields){const f=p.fields.find(f=>f.id===item.id);if(review){f.label=item.label;if(f.role!=='pageNumber'){f.role=item.role;f.editable=item.role!=='fixed';}if(item.day)f.day=item.day;}else values[item.id]=item.value;}
          if(!review){const c=document.createElement('canvas').getContext('2d');pending=requestFields.filter(f=>{try{textPlan(c,f,values[f.id],session.fonts);return false;}catch{return true;}});if(pending.length)status('Ajustando '+pending.length+' campo(s) ao espaço da página '+p.number+'…');}
        }
        if(!review){r.generated=true;r.artReviewed=false;root.querySelector('#pdf-art-reviewed').checked=false;await ctx.save();}else{model.visualLayout=structuredClone(layout);model.extractionStatus='pending';await ctx.save();}if(stopped)break;
      }
      const issues=review?[]:errors();status(issues.length?issues[0]+' Use “Preencher esta página” com uma descrição mais curta ou ajuste o campo.':(stopped?'Processo interrompido. Páginas concluídas foram preservadas.':'Campos prontos para revisão. Confira nomes, datas, sequência dos dias, fotos e mapas.'));display();
    }catch(e){status(e.message+(review?' O original está guardado; confira os campos disponíveis nesta revisão.':' As páginas já preenchidas permanecem salvas.'));}finally{busy=false;root.querySelectorAll('button,select').forEach(el=>el.disabled=false);root.querySelector('#pdf-cancel').hidden=true;}
  }
  if(!review&&!Object.keys(values).length&&layout.pages.some(p=>p.day)){
    const planner=document.createElement('div');planner.className='pdf-toolbar';planner.innerHTML='<label>Dias de programação <input id="pdf-day-count" type="number" min="1" max="30" value="'+new Set(layout.pages.filter(p=>p.day).map(p=>p.day)).size+'"></label><button class="outline-button" type="button">Ajustar sequência de dias</button><small>Reutiliza as páginas diárias e de continuação do modelo. Confira a sequência antes de gerar.</small>';root.querySelector('.pdf-brief-panel').append(planner);
    planner.querySelector('button').onclick=async()=>{try{if(busy||Object.keys(values).length)throw Error('A sequência já está em edição. Crie outro roteiro para alterar a quantidade de dias.');r.visualLayout=adaptDays(layout,Number(planner.querySelector('input').value));session.layout=r.visualLayout;await ctx.save();mount(root,{session,r,ctx,review:false});}catch(e){status(e.message);}};
  }
  root.querySelector('#pdf-auto').onclick=()=>generate(true);root.querySelector('#pdf-page-ai').onclick=()=>generate(false);
  root.querySelector('#pdf-save').onclick=async()=>{try{collect();if(review){model.visualLayout=layout;model.layout='original-pdf';model.extractionStatus='reviewed';model.subtitle=layout.pages.length+' páginas · visual original preservado';delete model.extractedDraft;}await ctx.save();status(review?'Modelo salvo. Use “Novo roteiro” para preencher uma nova viagem.':'Roteiro salvo.');if(review)ctx.done?.();}catch(e){status(e.message);}};
  if(!review)root.querySelector('#pdf-download').onclick=async()=>{if(busy)return;try{collect();const issues=errors();if(issues.length)throw Error(issues[0]);if(!r.artReviewed){root.querySelector('.pdf-brief-panel').open=true;throw Error('Confira fotos e mapas e marque a revisão antes de baixar.');}const missing=layout.pages.flatMap(p=>p.fields).filter(f=>f.editable&&!Object.hasOwn(values,f.id));if(missing.length)throw Error('Ainda há '+missing.length+' campos com dados do modelo. Preencha o roteiro com IA ou revise cada página antes de baixar.');busy=true;const {PDFDocument}=await import('./vendor/pdf-lib/pdf-lib.mjs'),pdf=await PDFDocument.create();for(const p of layout.pages){status('Preparando PDF · página '+p.number+'…');const c=document.createElement('canvas');await exclusive(()=>sourcePage(p).then(page=>renderPage(page,c,p,values,session.fonts,{scale:2})));const png=await pdf.embedPng(await(await fetch(c.toDataURL('image/png'))).arrayBuffer());pdf.addPage([p.width,p.height]).drawImage(png,{x:0,y:0,width:p.width,height:p.height});c.width=c.height=1;}await ctx.save();const url=URL.createObjectURL(new Blob([await pdf.save()],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=r.name.replace(/[\\/:*?"<>|]/g,'-')+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);status('PDF pronto. A edição permanece salva no portal.');}catch(e){status(e.message);}finally{busy=false;}};
  display();if(review&&autoClassify)generate(true);if(!review&&r.autoFillPending){r.autoFillPending=false;generate(true);}
}
